import React, { useEffect, useId, useRef, useState } from "react";
import {
  pudding,
  useWidgetInteraction,
  useWidgetLocale,
  useWidgetState,
  type SessionCandidate as SDKSessionCandidate,
} from "@pudding/widget";
import {
  Bot,
  Check,
  ChevronDown,
  Crosshair,
  Eye,
  EyeOff,
  Flame,
  HeartPulse,
  Package,
  Pause,
  Play,
  Radio,
  RotateCcw,
  Shield,
  ShieldAlert,
  Skull,
  Sparkles,
  Swords,
  Trophy,
  UserRound,
  UsersRound,
  Volume2,
  VolumeX,
  X,
  Zap,
} from "lucide-react";
import type { Seat, TerrainType, WeaponId } from "./types";
import {
  COL_LETTERS,
  seatsForCount,
  isBotParticipant,
  WEAPONS,
  chebyshevDist,
  isInStorm,
  canAgentSeeAgent,
  canAgentSeeTile,
  attackRangeFor,
  parseCoord,
} from "./rules";
import {
  lobby,
  position,
  start,
  dropIn,
  takeAction,
  stepBotTurn,
  pause,
  resume,
} from "./game";
import {
  t,
  setLocale,
  seatLabel,
  seatShortLabel,
  botNameForSeat,
  weaponLabel,
  terrainLabel,
} from "./text";
import {
  isSoundEnabled,
  setSoundEnabled,
  playSelectSound,
  playDropSound,
  playMoveSound,
  playLootSound,
  playHealSound,
  playAttackSound,
  playKillSound,
  playVictorySound,
} from "./sound";
import "./style.css";

type SessionCandidate = SDKSessionCandidate & {
  kind?: "session" | "external";
  connected?: boolean;
};
type Candidates = Omit<
  Awaited<ReturnType<typeof pudding.interaction.candidates>>,
  "sessions"
> & { sessions: SessionCandidate[] };

const interaction = pudding.interaction as typeof pudding.interaction & {
  onCandidatesChanged?: (listener: () => void) => () => void;
};

interface PlayerInfo {
  id: string;
  name: string;
  isHuman: boolean;
  isBot: boolean;
  model?: SessionCandidate["model"];
}

