import type { WeaponId } from "./types";

let soundEnabled = true;
let audioCtx: AudioContext | null = null;
let masterBus: GainNode | null = null;
let noiseBuffer: AudioBuffer | null = null;

export function isSoundEnabled(): boolean {
  return soundEnabled;
}

export function setSoundEnabled(val: boolean): void {
  soundEnabled = val;
}

function getAudioGraph(): { ctx: AudioContext; out: AudioNode } | null {
  if (!soundEnabled || typeof window === "undefined") return null;
  try {
    if (!audioCtx) {
      const Ctx =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext })
          .webkitAudioContext;
      if (!Ctx) return null;
      audioCtx = new Ctx();

      const presence = audioCtx.createBiquadFilter();
      presence.type = "highshelf";
      presence.frequency.value = 2400;
      presence.gain.value = 5.5;

      const comp = audioCtx.createDynamicsCompressor();
      comp.threshold.value = -14;
      comp.knee.value = 10;
      comp.ratio.value = 4.0;
      comp.attack.value = 0.002;
      comp.release.value = 0.14;

      masterBus = audioCtx.createGain();
      masterBus.gain.value = 0.92;

      masterBus.connect(presence);
      presence.connect(comp);
      comp.connect(audioCtx.destination);
    }
    if (audioCtx.state === "suspended") {
      void audioCtx.resume();
    }
    return { ctx: audioCtx, out: masterBus || audioCtx.destination };
  } catch {
    return null;
  }
}

function getWhiteNoiseBuffer(ctx: AudioContext): AudioBuffer {
  if (noiseBuffer && noiseBuffer.sampleRate === ctx.sampleRate) {
    return noiseBuffer;
  }
  const length = ctx.sampleRate * 1.5;
  const buf = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < length; i++) {
    data[i] = Math.random() * 2 - 1;
  }
  noiseBuffer = buf;
  return buf;
}

function playTone(
  freqStart: number,
  freqEnd: number,
  duration: number,
  type: OscillatorType = "triangle",
  gainPeak = 0.2,
  delay = 0,
) {
  const g = getAudioGraph();
  if (!g) return;
  const { ctx, out } = g;
  const now = ctx.currentTime + delay;

  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(Math.max(20, freqStart), now);
  if (freqEnd !== freqStart) {
    osc.frequency.exponentialRampToValueAtTime(
      Math.max(20, freqEnd),
      now + duration,
    );
  }

  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(gainPeak, now + 0.005);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

  osc.connect(gain);
  gain.connect(out);
  osc.start(now);
  osc.stop(now + duration + 0.02);
}

function playNoiseBurst(
  duration: number,
  filterType: BiquadFilterType,
  freqStart: number,
  freqEnd: number,
  qValue: number,
  gainPeak: number,
  delay = 0,
) {
  const g = getAudioGraph();
  if (!g) return;
  const { ctx, out } = g;
  const now = ctx.currentTime + delay;

  const src = ctx.createBufferSource();
  src.buffer = getWhiteNoiseBuffer(ctx);

  const filter = ctx.createBiquadFilter();
  filter.type = filterType;
  filter.Q.value = qValue;
  filter.frequency.setValueAtTime(Math.max(40, freqStart), now);
  if (freqEnd !== freqStart) {
    filter.frequency.exponentialRampToValueAtTime(
      Math.max(40, freqEnd),
      now + duration,
    );
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.linearRampToValueAtTime(gainPeak, now + 0.004);
  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

  src.connect(filter);
  filter.connect(gain);
  gain.connect(out);

  src.start(now);
  src.stop(now + duration + 0.02);
}

export function playSelectSound(): void {
  playNoiseBurst(0.022, "bandpass", 3600, 2000, 2.2, 0.22, 0);
  playTone(1480, 2220, 0.038, "sine", 0.15, 0);
}

/**
 * Parachute wind rush + landing thud + metallic bolt rack.
 */
export function playDropSound(): void {
  playNoiseBurst(0.22, "bandpass", 1600, 420, 1.4, 0.34, 0);
  playTone(130, 42, 0.16, "sine", 0.38, 0.14);
  // Metallic weapon cocking double-clack
  playNoiseBurst(0.03, "highpass", 3200, 5200, 2.0, 0.28, 0.22);
  playTone(1850, 950, 0.035, "square", 0.12, 0.22);
  playNoiseBurst(0.035, "highpass", 3600, 4800, 2.0, 0.3, 0.28);
}

/**
 * Crisp two-step tactical boot footsteps.
 */
export function playMoveSound(): void {
  playNoiseBurst(0.04, "bandpass", 950, 420, 1.8, 0.24, 0);
  playTone(140, 55, 0.05, "sine", 0.2, 0);
  playNoiseBurst(0.04, "bandpass", 1100, 480, 1.8, 0.24, 0.08);
  playTone(155, 60, 0.05, "sine", 0.2, 0.08);
}

/**
 * Supply crate metallic latch + bright upgrade arpeggio.
 */
export function playLootSound(): void {
  playNoiseBurst(0.035, "highpass", 2800, 4600, 1.8, 0.28, 0);
  const notes = [587.33, 880, 1174.66, 1760];
  notes.forEach((n, idx) => {
    playTone(n, n * 1.01, 0.12, "triangle", 0.18, 0.04 + idx * 0.045);
  });
}

/**
 * Medical syringe hiss + restorative harmonic chord.
 */
export function playHealSound(): void {
  playNoiseBurst(0.12, "bandpass", 4200, 2400, 2.4, 0.18, 0);
  const notes = [523.25, 659.25, 783.99, 1046.5];
  notes.forEach((n, idx) => {
    playTone(n, n, 0.22, "sine", 0.16, 0.05 + idx * 0.05);
  });
}

/**
 * Weapon-specific ballistic fire & explosion synthesizer.
 */
export function playAttackSound(
  weapon: WeaponId | "grenade" | "storm" | null,
): void {
  if (weapon === "grenade") {
    // Grenade whistle + heavy concussive explosion
    playTone(1200, 380, 0.14, "sine", 0.18, 0);
    playNoiseBurst(0.42, "lowpass", 1600, 140, 1.2, 0.65, 0.14);
    playTone(160, 28, 0.42, "sawtooth", 0.5, 0.14);
    playTone(95, 24, 0.46, "sine", 0.55, 0.14);
    return;
  }

  if (weapon === "sniper" || weapon === "awm") {
    // Piercing supersonic sniper crack + deep sub-bass punch + brass shell ping
    playNoiseBurst(0.05, "highpass", 2600, 6200, 1.5, 0.6, 0);
    playNoiseBurst(0.28, "bandpass", 1400, 240, 1.1, 0.52, 0.01);
    playTone(280, 36, 0.3, "sawtooth", 0.48, 0);
    playTone(120, 28, 0.34, "sine", 0.52, 0);
    // Brass shell casing hitting ground
    playTone(3520, 3320, 0.08, "sine", 0.14, 0.28);
    playTone(3720, 3520, 0.09, "sine", 0.12, 0.35);
    return;
  }

  if (weapon === "shotgun") {
    // Heavy close-quarters shotgun blast + pump rack
    playNoiseBurst(0.18, "bandpass", 1800, 280, 1.0, 0.58, 0);
    playTone(190, 38, 0.22, "sawtooth", 0.45, 0);
    playNoiseBurst(0.04, "highpass", 3000, 4800, 2.0, 0.26, 0.22);
    return;
  }

  // Default: Assault Rifle / SMG 3-round burst
  for (let i = 0; i < 3; i++) {
    const d = i * 0.065;
    playNoiseBurst(0.055, "bandpass", 2400, 520, 1.3, 0.42, d);
    playTone(240, 52, 0.065, "sawtooth", 0.32, d);
  }
}

/**
 * Elimination K.I.A impact stinger.
 */
export function playKillSound(
  weapon: WeaponId | "grenade" | "storm" | null,
): void {
  playAttackSound(weapon);
  // Crisp kill confirmation chime + sub impact
  playTone(880, 1318.5, 0.14, "triangle", 0.28, 0.22);
  playTone(1760, 1760, 0.24, "sine", 0.24, 0.29);
}

/**
 * "Winner Winner Chicken Dinner" triumphant brass & synth fanfare.
 */
export function playVictorySound(): void {
  playNoiseBurst(0.06, "highpass", 2200, 5000, 1.5, 0.45, 0);
  playTone(140, 36, 0.3, "sine", 0.45, 0);

  const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5, 1567.98, 2093.0];
  notes.forEach((n, idx) => {
    const d = 0.1 + idx * 0.072;
    const dur = idx === notes.length - 1 ? 0.7 : 0.22;
    playTone(n, n, dur, "triangle", 0.25, d);
    playTone(n * 1.5, n * 1.5, dur * 0.8, "sine", 0.11, d);
    playTone(n * 0.5, n * 0.5, dur * 0.9, "sawtooth", 0.08, d);
  });
}

files.src/style.css:
:root {
  color-scheme: dark;
  --br-bg-deep: #060a12;
  --br-bg-panel: rgba(15, 23, 42, 0.86);
  --br-gold: #f59e0b;
  --br-gold-bright: #fde047;
  --br-cyan: #38bdf8;
  --br-emerald: #22c55e;
  --br-crimson: #ef4444;
  --br-text-main: #f8fafc;
  --br-text-muted: #94a3b8;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  background: var(--br-bg-deep);
  color: var(--br-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang SC",
    "Microsoft YaHei", sans-serif;
  overflow-x: hidden;
  user-select: none;
}

/* Full-Bleed Tactical Command Center Container (Zero Vertical Shift) */
.br-app {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 10px 16px 14px;
  gap: 10px;
  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(17, 28, 45, 0.92) 0%,
      rgba(8, 13, 24, 0.98) 68%,
      #04070d 100%
    ),
    repeating-linear-gradient(
      0deg,
      rgba(56, 189, 248, 0.018) 0px,
      rgba(56, 189, 248, 0.018) 1px,
      transparent 1px,
      transparent 24px
    );
  overflow: hidden;
}

/* Top Bar */
.br-topbar {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 14px;
  border-radius: 12px;
  background: rgba(7, 11, 20, 0.88);
  border: 1px solid rgba(245, 158, 11, 0.25);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.42);
  backdrop-filter: blur(12px);
  flex-wrap: wrap;
  flex-shrink: 0;
}

.br-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.br-emblem {
  display: flex;
  align-items: center;
  justify-content: center;
}

.br-brand h1 {
  font-size: 16.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  background: linear-gradient(135deg, #fef08a 0%, #f59e0b 65%, #fbbf24 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.br-status-pills {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-left: 4px;
}

.br-phase-pill,
.br-alive-pill,
.br-storm-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  white-space: nowrap;
}

.br-phase-pill {
  background: rgba(245, 158, 11, 0.16);
  border: 1px solid rgba(245, 158, 11, 0.42);
  color: #fde047;
}

.br-alive-pill {
  background: rgba(34, 197, 94, 0.14);
  border: 1px solid rgba(34, 197, 94, 0.38);
  color: #86efac;
}

.br-storm-pill {
  background: rgba(56, 189, 248, 0.14);
  border: 1px solid rgba(56, 189, 248, 0.38);
  color: #7dd3fc;
}

.br-toolbar {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.br-top-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 31px;
  padding: 0 11px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(30, 41, 59, 0.75);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.16s ease;
}

.br-top-btn.is-icon {
  padding: 0 8px;
}

.br-top-btn:hover:not(:disabled) {
  border-color: rgba(245, 158, 11, 0.55);
  background: rgba(51, 65, 85, 0.88);
  color: #ffffff;
}

.br-top-btn.is-active {
  background: rgba(245, 158, 11, 0.22);
  border-color: rgba(251, 191, 36, 0.65);
  color: #fde047;
}

.br-top-btn.is-primary {
  background: linear-gradient(135deg, #d97706 0%, #b45309 100%);
  border-color: #fbbf24;
  color: #fffbeb;
}

/* Error Toast */
.br-error-toast {
  position: absolute;
  top: 60px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  border-radius: 10px;
  background: rgba(127, 29, 29, 0.95);
  border: 1px solid #f87171;
  color: #fef2f2;
  font-size: 12.5px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.55);
}

.br-error-toast button {
  background: transparent;
  border: none;
  color: #fecaca;
  cursor: pointer;
  display: flex;
}

/* Main 3-Column Tactical Arena */
.br-arena {
  position: relative;
  z-index: 5;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(195px, 232px) minmax(0, 1fr) minmax(195px, 232px);
  gap: 12px;
  align-items: stretch;
  min-height: 0;
}

.br-wing {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 10px;
}

/* Operative Vitality Card (Fixed Height = Zero Vertical Jump) */
.br-agent-card {
  position: relative;
  flex: 1;
  min-height: 146px;
  max-height: 176px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 10px 12px;
  border-radius: 13px;
  background: linear-gradient(
    165deg,
    rgba(30, 41, 59, 0.88) 0%,
    rgba(15, 23, 42, 0.95) 100%
  );
  border: 1px solid rgba(148, 163, 184, 0.2);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.36);
  overflow: hidden;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.br-agent-card.is-turn {
  border-color: #fbbf24;
  box-shadow:
    0 0 0 2px rgba(251, 191, 36, 0.28),
    0 10px 26px rgba(245, 158, 11, 0.22);
}

.br-agent-card.is-winner {
  border-color: #fde047;
  box-shadow: 0 0 24px rgba(250, 204, 21, 0.35);
}

.br-agent-card.is-eliminated {
  opacity: 0.58;
  filter: saturate(0.4);
}

.br-agent-top {
  display: flex;
  align-items: center;
  gap: 9px;
}

/* Operative Avatar */
.br-avatar-wrap {
  position: relative;
  width: 38px;
  height: 38px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.br-avatar-wrap.is-token {
  width: 26px;
  height: 26px;
}

.br-winner-star-ring {
  position: absolute;
  inset: -4px;
  width: calc(100% + 8px);
  height: calc(100% + 8px);
  animation: brSpin 12s linear infinite;
}

@keyframes brSpin {
  to {
    transform: rotate(360deg);
  }
}

.br-avatar-circle {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: #1e293b;
  border: 1.5px solid rgba(245, 158, 11, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  color: #fde047;
}

.br-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.br-seat-num-badge {
  position: absolute;
  bottom: -3px;
  right: -4px;
  z-index: 3;
  padding: 0 4px;
  border-radius: 5px;
  background: #0f172a;
  border: 1px solid rgba(251, 191, 36, 0.65);
  color: #fde047;
  font-size: 9px;
  font-weight: 800;
}

.br-agent-meta {
  flex: 1;
  min-width: 0;
}

.br-agent-name-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
}

.br-agent-name {
  font-size: 12.5px;
  font-weight: 700;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.br-kill-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 10.5px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 999px;
  background: rgba(239, 68, 68, 0.18);
  border: 1px solid rgba(248, 113, 113, 0.4);
  color: #fca5a5;
  flex-shrink: 0;
}

.br-agent-sub-row {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 3px;
}

.br-weapon-pill {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 10px;
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(245, 158, 11, 0.15);
  border: 1px solid rgba(245, 158, 11, 0.35);
  color: #fde047;
}

.br-coord-pill {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(56, 189, 248, 0.16);
  color: #7dd3fc;
}

.br-coord-pill::before {
  content: attr(data-coord);
}

.br-out-pill {
  font-size: 10px;
  color: #f87171;
  font-weight: 700;
}

/* Vitality HP & Shield Bars */
.br-vitality-bars {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.br-bar-track {
  position: relative;
  height: 13px;
  border-radius: 999px;
  background: rgba(7, 11, 20, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.16);
  overflow: hidden;
}

.br-bar-fill {
  height: 100%;
  transition: width 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.br-bar-fill.is-hp {
  background: linear-gradient(90deg, #16a34a, #22c55e);
}
.br-bar-fill.is-hp.is-warn {
  background: linear-gradient(90deg, #d97706, #f59e0b);
}
.br-bar-fill.is-hp.is-critical {
  background: linear-gradient(90deg, #dc2626, #ef4444);
}

.br-bar-fill.is-shield {
  background: linear-gradient(90deg, #0284c7, #38bdf8);
}

.br-bar-label {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9.5px;
  font-weight: 800;
  color: #ffffff;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.85);
}

/* Radio & Action Log Slot */
.br-agent-radio-slot {
  height: 38px;
  display: flex;
  align-items: center;
  padding: 4px 8px;
  border-radius: 8px;
  background: rgba(7, 11, 20, 0.6);
  border: 1px solid rgba(148, 163, 184, 0.12);
  overflow: hidden;
}

.br-radio-quote {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: #fde047;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.br-radio-icon {
  flex-shrink: 0;
}

.br-action-note {
  font-size: 11px;
  color: #cbd5e1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.br-action-placeholder {
  font-size: 11px;
  color: rgba(148, 163, 184, 0.45);
}

/* K.I.A Eliminated Stamp */
.br-kia-stamp {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 8;
  padding: 2px 8px;
  border: 2px solid #ef4444;
  border-radius: 5px;
  background: rgba(69, 10, 10, 0.92);
  color: #fca5a5;
  font-size: 10.5px;
  font-weight: 900;
  transform: rotate(-12deg);
  animation: brStampSlam 0.34s cubic-bezier(0.18, 0.89, 0.32, 1.28);
}

.br-kia-stamp span::before {
  content: attr(data-stamp);
}

@keyframes brStampSlam {
  0% {
    opacity: 0;
    transform: rotate(-26deg) scale(2.2);
  }
  100% {
    opacity: 1;
    transform: rotate(-12deg) scale(1);
  }
}

/* Center Stage: Ticker + 8x6 Tactical Grid + Control Dock */
.br-center-stage {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  min-height: 0;
}

.br-ticker-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 14px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.88);
  border: 1px solid rgba(245, 158, 11, 0.28);
  font-size: 12px;
  flex-shrink: 0;
}

.br-ticker-left {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #f8fafc;
  font-weight: 600;
  min-width: 0;
}

.br-ticker-left span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.br-ticker-icon {
  color: #f59e0b;
  flex-shrink: 0;
}

.br-turn-tag {
  font-size: 11.5px;
  font-weight: 700;
  color: #fde047;
  white-space: nowrap;
  flex-shrink: 0;
}

/* 8x6 Tactical Map Board */
.br-map-container {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 8px 10px 10px;
  border-radius: 14px;
  background: rgba(8, 14, 26, 0.92);
  border: 1px solid rgba(56, 189, 248, 0.25);
  box-shadow:
    inset 0 0 30px rgba(0, 0, 0, 0.65),
    0 10px 30px rgba(0, 0, 0, 0.45);
  min-height: 360px;
  overflow: hidden;
}

.br-welcome-overlay {
  position: absolute;
  inset: 0;
  z-index: 25;
  background: rgba(6, 10, 18, 0.86);
  backdrop-filter: blur(6px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 10px;
  padding: 20px;
}

.br-welcome-overlay h2 {
  font-size: 19px;
  font-weight: 800;
  color: #fde047;
}

.br-welcome-overlay p {
  max-width: 460px;
  font-size: 13px;
  line-height: 1.55;
  color: #cbd5e1;
}

.br-cta-btn {
  margin-top: 6px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 22px;
  border-radius: 999px;
  border: 1px solid #fde047;
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  color: #fffbeb;
  font-size: 13.5px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(245, 158, 11, 0.35);
}

.br-col-headers {
  display: grid;
  grid-template-columns: 22px repeat(8, 1fr);
  gap: 5px;
  margin-bottom: 4px;
  flex-shrink: 0;
}

.br-col-label {
  text-align: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 800;
  color: #64748b;
}

.br-grid-body {
  flex: 1;
  display: grid;
  grid-template-columns: 22px 1fr;
  gap: 5px;
  min-height: 0;
}

.br-row-headers {
  display: grid;
  grid-template-rows: repeat(6, 1fr);
  gap: 5px;
}

.br-row-label {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  font-weight: 800;
  color: #64748b;
}

.br-tiles-grid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  grid-template-rows: repeat(6, 1fr);
  gap: 5px;
  min-height: 0;
}

/* SVG Bullet Tracer & Explosion Ring */
.br-tracer-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
}

.br-tracer-line {
  stroke-width: 0.9;
  stroke-linecap: round;
  animation: brTracerFade 0.95s ease-out forwards;
}

.br-tracer-line.is-bullet {
  stroke: #fde047;
  filter: drop-shadow(0 0 4px #f59e0b);
}

.br-tracer-line.is-grenade {
  stroke: #ef4444;
  stroke-dasharray: 2 1.5;
  filter: drop-shadow(0 0 5px #ef4444);
}

.br-impact-ring {
  fill: rgba(239, 68, 68, 0.35);
  stroke: #fde047;
  stroke-width: 0.6;
  animation: brImpactPulse 0.85s ease-out forwards;
}

@keyframes brTracerFade {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

@keyframes brImpactPulse {
  0% {
    transform: scale(0.5);
    transform-origin: center;
    opacity: 1;
  }
  100% {
    transform: scale(1.8);
    transform-origin: center;
    opacity: 0;
  }
}

/* Individual Tactical Tile */
.br-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 4px 5px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  background: rgba(30, 41, 59, 0.62);
  color: #f8fafc;
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.14s ease, border-color 0.14s ease, background 0.14s ease;
}

.br-tile.is-ter-base {
  background: linear-gradient(
    145deg,
    rgba(120, 53, 15, 0.45),
    rgba(30, 41, 59, 0.78)
  );
  border-color: rgba(245, 158, 11, 0.35);
}

.br-tile.is-ter-tower {
  background: linear-gradient(
    145deg,
    rgba(12, 74, 110, 0.48),
    rgba(30, 41, 59, 0.78)
  );
  border-color: rgba(56, 189, 248, 0.35);
}

.br-tile.is-ter-bush {
  background: linear-gradient(
    145deg,
    rgba(20, 83, 45, 0.45),
    rgba(30, 41, 59, 0.75)
  );
  border-color: rgba(34, 197, 94, 0.3);
}

.br-tile.is-ter-bunker {
  background: linear-gradient(
    145deg,
    rgba(51, 65, 85, 0.75),
    rgba(15, 23, 42, 0.85)
  );
  border-color: rgba(148, 163, 184, 0.38);
}

/* Electromagnetic Storm Overlay */
.br-tile.is-storm {
  background: repeating-linear-gradient(
    -45deg,
    rgba(88, 28, 135, 0.32),
    rgba(88, 28, 135, 0.32) 5px,
    rgba(15, 23, 42, 0.78) 5px,
    rgba(15, 23, 42, 0.78) 10px
  );
  border-color: rgba(192, 132, 252, 0.42);
}

/* Fog of War Shroud */
.br-tile.is-fog {
  opacity: 0.56;
  filter: brightness(0.75);
}

/* Interactive Move & Attack Highlights */
.br-tile.is-move-target {
  border-color: rgba(56, 189, 248, 0.75);
  box-shadow: inset 0 0 10px rgba(56, 189, 248, 0.22);
}

.br-tile.is-move-target:hover {
  transform: scale(1.03);
  border-color: #38bdf8;
}

.br-tile.is-attack-target {
  border-color: #ef4444;
  box-shadow:
    0 0 0 1px rgba(239, 68, 68, 0.55),
    inset 0 0 14px rgba(220, 38, 38, 0.38);
}

.br-tile.is-attack-target:hover {
  transform: scale(1.04);
}

.br-tile-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  font-size: 9.5px;
  line-height: 1;
}

.br-tile-coord {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-weight: 700;
  color: rgba(148, 163, 184, 0.75);
}

.br-tile-icons {
  display: inline-flex;
  gap: 2px;
  font-size: 10px;
}

.br-tile-mid {
  display: flex;
  align-items: center;
  justify-content: center;
}

.br-crate-badge {
  font-size: 9.5px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 4px;
  white-space: nowrap;
}

.br-crate-badge.is-airdrop {
  background: rgba(220, 38, 38, 0.35);
  border: 1px solid #fde047;
  color: #fef08a;
  animation: brAirdropPulse 1.1s infinite alternate;
}

@keyframes brAirdropPulse {
  from {
    box-shadow: 0 0 4px rgba(250, 204, 21, 0.3);
  }
  to {
    box-shadow: 0 0 12px rgba(250, 204, 21, 0.85);
  }
}

.br-crate-badge.is-supply {
  background: rgba(245, 158, 11, 0.2);
  border: 1px solid rgba(245, 158, 11, 0.45);
  color: #fde047;
}

.br-crate-badge.is-deathbox {
  background: rgba(148, 163, 184, 0.22);
  color: #cbd5e1;
}

.br-ping-blip {
  font-size: 9.5px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 999px;
  background: rgba(239, 68, 68, 0.35);
  border: 1px solid #f87171;
  color: #fecaca;
  animation: brAirdropPulse 0.8s infinite alternate;
}

.br-tile-agents {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-wrap: wrap;
}

.br-map-token {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 1px 3px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.9);
  border: 1px solid rgba(148, 163, 184, 0.4);
}

.br-map-token.is-self {
  border-color: #4ade80;
  box-shadow: 0 0 8px rgba(34, 197, 94, 0.45);
}

.br-map-token.is-enemy {
  border-color: #f87171;
}

.br-map-token.is-active-turn {
  border-color: #fde047;
  box-shadow: 0 0 10px rgba(250, 204, 21, 0.65);
}

.br-token-wep {
  font-size: 8.5px;
  font-weight: 800;
  color: #fde047;
  padding-right: 2px;
}

.br-token-wep::before {
  content: attr(data-wep);
}

.br-floating-dmg {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 20;
  padding: 1px 5px;
  border-radius: 5px;
  background: #dc2626;
  color: #fff;
  font-size: 11px;
  font-weight: 900;
  animation: brFloatUp 0.95s ease-out forwards;
}

@keyframes brFloatUp {
  0% {
    opacity: 1;
    transform: translateY(4px) scale(1.2);
  }
  100% {
    opacity: 0;
    transform: translateY(-12px) scale(0.95);
  }
}

/* Bottom Tactical Control Dock */
.br-control-dock {
  flex-shrink: 0;
  min-height: 58px;
  padding: 8px 14px;
  border-radius: 12px;
  background: rgba(11, 17, 32, 0.92);
  border: 1px solid rgba(245, 158, 11, 0.28);
  display: flex;
  align-items: center;
}

.br-dock-inner {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.br-dock-prompt {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: #fde047;
}

.br-beacon-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fde047;
  box-shadow: 0 0 8px #f59e0b;
  flex-shrink: 0;
}

.br-combat-actions-row,
.br-radio-row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.br-ap-badge {
  font-size: 11.5px;
  font-weight: 800;
  padding: 4px 9px;
  border-radius: 7px;
  background: rgba(245, 158, 11, 0.2);
  border: 1px solid #fbbf24;
  color: #fde047;
}

.br-act-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 32px;
  padding: 0 11px;
  border-radius: 7px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(30, 41, 59, 0.85);
  color: #f8fafc;
}

.br-act-btn.is-loot {
  border-color: rgba(245, 158, 11, 0.5);
  color: #fde047;
}

.br-act-btn.is-heal {
  border-color: rgba(34, 197, 94, 0.5);
  color: #86efac;
}

.br-act-btn.is-grenade {
  border-color: rgba(239, 68, 68, 0.5);
  color: #fca5a5;
}

.br-act-btn.is-grenade.is-selected {
  background: #dc2626;
  color: #ffffff;
}

.br-act-btn.is-guard {
  border-color: rgba(56, 189, 248, 0.5);
  color: #7dd3fc;
}

.br-act-btn.is-gold {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border-color: #fde047;
  color: #fffbeb;
}

.br-act-btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.br-radio-input {
  flex: 1;
  min-width: 160px;
  height: 32px;
  padding: 0 11px;
  border-radius: 7px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(7, 11, 20, 0.85);
  color: #f8fafc;
  font-size: 12px;
  outline: none;
}

.br-radio-input:focus {
  border-color: #fbbf24;
}

.br-standby-bar {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12.5px;
  color: #cbd5e1;
}

.br-gold-icon {
  color: #fde047;
}

/* Modal & Fixed-Position Custom Dropdowns */
.br-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(5, 8, 17, 0.8);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.br-modal-card {
  width: 100%;
  max-width: 640px;
  border-radius: 18px;
  background: #0f172a;
  border: 1px solid rgba(245, 158, 11, 0.38);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.65);
  display: flex;
  flex-direction: column;
  max-height: 90vh;
}

.br-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}

.br-modal-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.br-modal-title-row h3 {
  font-size: 16px;
  font-weight: 800;
  color: #fde047;
}

.br-modal-close {
  background: transparent;
  border: none;
  color: #94a3b8;
  cursor: pointer;
}

.br-modal-body {
  padding: 16px 18px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.br-config-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.br-config-label {
  font-size: 12px;
  font-weight: 700;
  color: #94a3b8;
}

.br-mode-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.br-mode-tab {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(30, 41, 59, 0.6);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.br-mode-tab.is-active {
  background: rgba(245, 158, 11, 0.2);
  border-color: #fbbf24;
  color: #fde047;
}

.br-seats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.br-seat-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.br-seat-field-label {
  font-size: 11.5px;
  font-weight: 700;
  color: #cbd5e1;
}

.br-select-wrap {
  position: relative;
}

.br-select-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 10px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: rgba(30, 41, 59, 0.75);
  color: #f8fafc;
  cursor: pointer;
}

.br-select-item-left {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.br-select-icon {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.br-select-icon.is-human {
  background: rgba(245, 158, 11, 0.2);
  color: #fde047;
}
.br-select-icon.is-bot {
  background: rgba(56, 189, 248, 0.2);
  color: #7dd3fc;
}
.br-select-icon.is-ai {
  background: rgba(168, 85, 247, 0.2);
  color: #d8b4fe;
}

.br-select-model-img {
  width: 26px;
  height: 26px;
  border-radius: 7px;
  object-fit: cover;
  flex-shrink: 0;
}

.br-select-texts {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
}

.br-select-title {
  font-size: 12.5px;
  color: #f8fafc;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.br-select-sub {
  font-size: 10.5px;
  color: #94a3b8;
}

.br-select-chevron {
  color: #94a3b8;
  transition: transform 0.15s ease;
  flex-shrink: 0;
}

.br-select-chevron.is-open {
  transform: rotate(180deg);
}

.br-select-menu {
  position: fixed;
  z-index: 999;
  max-height: 240px;
  overflow-y: auto;
  border-radius: 10px;
  background: #0f172a;
  border: 1px solid rgba(245, 158, 11, 0.55);
  box-shadow: 0 16px 38px rgba(0, 0, 0, 0.78);
  padding: 5px;
}

.br-select-option {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: #f8fafc;
  cursor: pointer;
}

.br-select-option:hover,
.br-select-option.is-selected {
  background: rgba(245, 158, 11, 0.16);
}

.br-select-check {
  color: #fde047;
}

.br-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 18px;
  border-top: 1px solid rgba(148, 163, 184, 0.16);
}

.br-modal-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 16px;
  border-radius: 9px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.br-modal-btn.is-ghost {
  background: transparent;
  border: 1px solid rgba(148, 163, 184, 0.3);
  color: #cbd5e1;
}

.br-modal-btn.is-confirm {
  background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%);
  border-color: #fde047;
  color: #fffbeb;
}

